"""Error hierarchy: every user-caused failure derives from TallybookError."""


class TallybookError(Exception):
    code = "error"

    def __init__(self, message="", detail=None):
        super().__init__(message)
        self.message = message
        self.detail = dict(detail) if detail else {}

    def __str__(self):
        return self.message


class ParseError(TallybookError):
    code = "parse"


class ValidationError(TallybookError):
    code = "validation"


class NotFoundError(TallybookError):
    code = "not_found"


class ConflictError(TallybookError):
    code = "conflict"
"""Plain data records: Account, Posting, Transaction."""
import datetime as _dt
from dataclasses import dataclass, field
from typing import Any, List, Optional, Tuple


@dataclass
class Account:
    path: str
    type: str
    currency: Optional[str] = None
    opened: Optional[_dt.date] = None
    closed: Optional[_dt.date] = None
    note: str = ""


@dataclass(frozen=True)
class Posting:
    account: str
    amount: Any  # Money or None
    note: str = ""


@dataclass
class Transaction:
    date: _dt.date
    payee: str
    narration: str = ""
    postings: List[Posting] = field(default_factory=list)
    tags: Tuple[str, ...] = ()
    flag: str = "*"
    id: Optional[int] = None
"""Strict dates, month arithmetic and periods."""
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta

from .errors import ParseError


class DateError(ParseError):
    pass


def is_date(x):
    return isinstance(x, date) and not isinstance(x, datetime)


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date '%s': expected text" % (text,))
    m = _DATE_RE.fullmatch(text)
    if not m:
        raise DateError("invalid date '%s': expected YYYY-MM-DD" % text)
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text) from None


def format_date(d):
    if not is_date(d):
        raise DateError("not a date: '%s'" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("year and month must be integers")
    if not 1 <= month <= 12 or not 1 <= year <= 9999:
        raise DateError("no such month: %s-%s" % (year, month))
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - timedelta(days=1)).day


def add_months(d, n):
    if not is_date(d):
        raise DateError("not a date: '%s'" % (d,))
    if not _is_int(n):
        raise DateError("months must be an integer, got '%s'" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    y, m = divmod(total, 12)
    m += 1
    if not 1 <= y <= 9999:
        raise DateError("date out of range: %s plus %d months" % (format_date(d), n))
    return date(y, m, min(d.day, last_day(y, m)))


@dataclass(frozen=True)
class Period:
    start: date
    end: date

    def __post_init__(self):
        if not is_date(self.start) or not is_date(self.end):
            raise DateError("period needs two dates, got '%s' and '%s'" % (self.start, self.end))
        if self.end < self.start:
            raise DateError("empty period: %s is before %s" % (format_date(self.end), format_date(self.start)))

    def contains(self, d):
        if not is_date(d):
            raise DateError("not a date: '%s'" % (d,))
        return self.start <= d <= self.end

    @property
    def days(self):
        return (self.end - self.start).days + 1

    def _kind(self):
        s, e = self.start, self.end
        if s.day != 1:
            return None
        if s.month == 1 and e.year == s.year and e.month == 12 and e.day == 31:
            return "year"
        if e.year == s.year and e.month == s.month and e.day == last_day(e.year, e.month):
            return "month"
        if (
            s.month in (1, 4, 7, 10)
            and e.year == s.year
            and e.month == s.month + 2
            and e.day == last_day(e.year, e.month)
        ):
            return "quarter"
        return None

    @property
    def label(self):
        kind = self._kind()
        s = self.start
        if kind == "year":
            return "%04d" % s.year
        if kind == "month":
            return "%04d-%02d" % (s.year, s.month)
        if kind == "quarter":
            return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
        return "%s..%s" % (format_date(self.start), format_date(self.end))

    def __str__(self):
        return self.label

    def next(self):
        kind = self._kind()
        s = self.start
        try:
            if kind == "year":
                return _year(s.year + 1)
            if kind == "month":
                return _month_after(s)
            if kind == "quarter":
                nxt = add_months(s, 3)
                return _span(nxt, add_months(nxt, 3) - timedelta(days=1))
            ns = self.end + timedelta(days=1)
            return Period(ns, ns + timedelta(days=self.days - 1))
        except OverflowError:
            raise DateError("period after %s is out of range" % self.label) from None

    @staticmethod
    def parse(text):
        return _parse_period(text)


def _span(a, b):
    return Period(a, b)


def _year(y):
    if not 1 <= y <= 9999:
        raise DateError("year %d is out of range" % y)
    return Period(date(y, 1, 1), date(y, 12, 31))


def _month_after(s):
    nxt = add_months(s, 1)
    return Period(nxt, date(nxt.year, nxt.month, last_day(nxt.year, nxt.month)))


def _month_of(y, m):
    return Period(date(y, m, 1), date(y, m, last_day(y, m)))


_YEAR_RE = re.compile(r"([0-9]{4})")
_MONTH_RE = re.compile(r"([0-9]{4})-([0-9]{2})")
_QUARTER_RE = re.compile(r"([0-9]{4})-Q([1-4])")


def _parse_period(text):
    if not isinstance(text, str):
        raise DateError("invalid period '%s': expected text" % (text,))
    try:
        m = _YEAR_RE.fullmatch(text)
        if m:
            return _year(int(m.group(1)))
        m = _MONTH_RE.fullmatch(text)
        if m:
            return _month_of(int(m.group(1)), int(m.group(2)))
        m = _QUARTER_RE.fullmatch(text)
        if m:
            y, q = int(m.group(1)), int(m.group(2))
            first = _month_of(y, 3 * q - 2)
            return Period(first.start, _month_of(y, 3 * q).end)
        parts = text.split("..")
        if len(parts) == 2:
            return Period(parse_date(parts[0]), parse_date(parts[1]))
    except (DateError, ValueError):
        pass
    raise DateError("invalid period '%s'" % text)


_STEPS = ("week", "month", "quarter", "year")


def _containing(d, step):
    if step == "week":
        start = d - timedelta(days=d.weekday())
        return Period(start, start + timedelta(days=6))
    if step == "month":
        return _month_of(d.year, d.month)
    if step == "quarter":
        q = (d.month - 1) // 3
        return Period(date(d.year, 3 * q + 1, 1), _month_of(d.year, 3 * q + 3).end)
    return _year(d.year)


def periods(start, end, step):
    if not is_date(start) or not is_date(end):
        raise DateError("periods needs two dates, got '%s' and '%s'" % (start, end))
    if not isinstance(step, str) or step not in _STEPS:
        raise DateError("unknown step '%s': expected week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("end %s is before start %s" % (format_date(end), format_date(start)))
    p = _containing(start, step)
    out = [p]
    while p.end < end:
        p = _containing(p.end + timedelta(days=1), step)
        out.append(p)
    return out
"""The ledger: validated transactions and balances."""
import re
from collections import defaultdict
from datetime import date

from .accounts import Chart
from .currency import RateTable
from .dates import is_date
from .errors import NotFoundError, ValidationError
from .model import Posting, Transaction
from .money import Money, format_minor


class LedgerError(ValidationError):
    pass


_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _text(value, what):
    if not isinstance(value, str) or "\n" in value or "\r" in value:
        raise LedgerError("%s must be text without a line break" % what)


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # -- validation -------------------------------------------------------
    def _build(self, tx, tx_id):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: '%s'" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("transaction date must be a date, got '%s'" % (tx.date,))
        if tx.flag not in ("*", "!"):
            raise LedgerError("flag must be '*' or '!', got '%s'" % (tx.flag,))
        _text(tx.payee, "payee")
        _text(tx.narration, "narration")
        if isinstance(tx.tags, str) or not hasattr(tx.tags, "__iter__"):
            raise LedgerError("tags must be a list of names")
        tags = set()
        for t in tx.tags:
            if not isinstance(t, str) or not _TAG_RE.fullmatch(t):
                raise LedgerError("invalid tag '%s'" % (t,))
            tags.add(t.lower())
        if not isinstance(tx.postings, (list, tuple)):
            raise LedgerError("postings must be a list")
        postings = list(tx.postings)
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: '%s'" % (p,))
            if not isinstance(p.account, str):
                raise LedgerError("posting account must be text")
            _text(p.note, "posting note")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("posting amount must be money or None")
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account '%s'" % p.account)
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, tx.date.isoformat()))
            if p.amount is not None:
                self._check_currency(p)
        blanks = [i for i, p in enumerate(postings) if p.amount is None]
        if len(blanks) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = defaultdict(int)
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] += p.amount.minor
        if blanks:
            i = blanks[0]
            off = sorted(c for c, v in sums.items() if v != 0)
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            old = postings[i]
            new = [Posting(old.account, Money(-sums[c], c), old.note) for c in off]
            for p in new:
                self._check_currency(p)
            postings[i : i + 1] = new
            sums = defaultdict(int)
            for p in postings:
                sums[p.amount.currency] += p.amount.minor
        bad = sorted(c for c, v in sums.items() if v != 0)
        if bad:
            raise LedgerError(
                "transaction does not balance: "
                + ", ".join("%s %s" % (c, format_minor(sums[c], c)) for c in bad)
            )
        return Transaction(tx.date, tx.payee, tx.narration, postings, tuple(sorted(tags)), tx.flag, tx_id)

    def _check_currency(self, p):
        want = self.chart.get(p.account).currency
        if want is not None and p.amount.currency != want:
            raise LedgerError(
                "account %s only holds %s, not %s" % (p.account, want, p.amount.currency)
            )

    def _assign_id(self, tx):
        if tx.id is None:
            return self._max_id + 1
        if not _is_int(tx.id) or tx.id < 1:
            raise LedgerError("transaction id must be an integer of at least 1, got '%s'" % (tx.id,))
        if tx.id in self._txs:
            raise LedgerError("transaction %d already exists" % tx.id)
        return tx.id

    # -- mutation ---------------------------------------------------------
    def add(self, tx):
        if isinstance(tx, Transaction):
            tx_id = self._assign_id(tx)
        else:
            tx_id = None
        stored = self._build(tx, tx_id)
        self._txs[stored.id] = stored
        self._max_id = max(self._max_id, stored.id)
        return stored

    def add_many(self, transactions):
        snapshot = (dict(self._txs), self._max_id)
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._max_id = snapshot
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: '%s'" % (tx,))
        if tx.id is not None and tx.id != id:
            raise LedgerError("transaction id %s does not match %s" % (tx.id, id))
        stored = self._build(tx, id)
        self._txs[id] = stored
        return stored

    def remove(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs.pop(id)

    # -- lookup -----------------------------------------------------------
    def get(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs[id]

    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    # -- balances ---------------------------------------------------------
    def _walk(self, as_of):
        if as_of is not None and not is_date(as_of):
            raise LedgerError("as_of must be a date, got '%s'" % (as_of,))
        for tx, p in self.postings():
            if as_of is None or tx.date <= as_of:
                yield p

    @staticmethod
    def _clean(acc):
        out = {}
        for a, cur in acc.items():
            cur = {c: v for c, v in cur.items() if v != 0}
            if cur:
                out[a] = cur
        return out

    def balances(self, as_of=None):
        acc = defaultdict(lambda: defaultdict(int))
        for p in self._walk(as_of):
            acc[p.account][p.amount.currency] += p.amount.minor
        return self._clean(acc)

    def rollup_balances(self, as_of=None):
        acc = defaultdict(lambda: defaultdict(int))
        for p in self._walk(as_of):
            parts = p.account.split(":")
            for i in range(1, len(parts) + 1):
                acc[":".join(parts[:i])][p.amount.currency] += p.amount.minor
        return self._clean(acc)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account '%s'" % (account,))
        sums = defaultdict(int)
        for p in self._walk(as_of):
            if p.account == account or (rollup and p.account.startswith(account + ":")):
                sums[p.amount.currency] += p.amount.minor
        if currency is not None:
            return Money(sums.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(sums.items()) if v != 0}
"""Shared builders for the test-suite (stdlib only)."""
from datetime import date

from tallybook.ledger import Ledger
from tallybook.model import Posting, Transaction
from tallybook.money import Money


def P(account, amount=None, note=""):
    """Posting from text: P("Assets:Cash", "-12.50 USD")."""
    return Posting(account, Money.parse(amount) if isinstance(amount, str) else amount, note)


def T(y, m, d, payee, *postings, narration="", tags=(), flag="*", id=None):
    return Transaction(date(y, m, d), payee, narration, list(postings), tuple(tags), flag, id)


SAMPLE_ACCOUNTS = [
    "Assets:Bank:Checking", "Assets:Cash", "Liabilities:Card", "Equity:Opening",
    "Income:Salary", "Expenses:Food", "Expenses:Rent",
]


def sample_ledger():
    """The sample book of the Reports section (ids 1-8, all USD)."""
    led = Ledger()
    for a in SAMPLE_ACCOUNTS:
        led.chart.add(a, currency="USD")
    chk = "Assets:Bank:Checking"
    for tx in [
        T(2024, 1, 1, "Opening", P(chk, "1000.00 USD"), P("Equity:Opening", "-1000.00 USD")),
        T(2024, 3, 1, "Acme", P(chk, "2500.00 USD"), P("Income:Salary", "-2500.00 USD")),
        T(2024, 3, 2, "Market", P("Expenses:Food", "42.50 USD"), P(chk, "-42.50 USD")),
        T(2024, 3, 5, "Landlord", P("Expenses:Rent", "900.00 USD"), P("Liabilities:Card", "-900.00 USD")),
        T(2024, 3, 10, "ATM", P("Assets:Cash", "100.00 USD"), P(chk, "-100.00 USD")),
        T(2024, 3, 12, "Corner", P("Expenses:Food", "12.00 USD"), P("Assets:Cash", "-12.00 USD")),
        T(2024, 4, 2, "Card payoff", P("Liabilities:Card", "900.00 USD"), P(chk, "-900.00 USD")),
        T(2024, 4, 3, "Market", P("Expenses:Food", "30.00 USD"), P(chk, "-30.00 USD")),
    ]:
        led.add(tx)
    return led
"""Money as integer minor units with a currency code."""
import re

from .currency import CURRENCIES, CurrencyError, currency as _currency
from .errors import ValidationError


class MoneyError(ValidationError):
    pass


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def round_div(n, d):
    if not _is_int(n) or not _is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (n, d))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %d" % d)
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return -q if n < 0 else q


def format_minor(minor, currency):
    exp = _currency(currency).exponent
    if not _is_int(minor):
        raise MoneyError("amount must be an integer number of minor units, got %r" % (minor,))
    sign = "-" if minor < 0 else ""
    whole, frac = divmod(abs(minor), 10 ** exp)
    if exp == 0:
        return "%s%d" % (sign, whole)
    return "%s%d.%s" % (sign, whole, str(frac).rjust(exp, "0"))


def parse_amount(text, currency):
    exp = _currency(currency).exponent
    if not isinstance(text, str):
        raise MoneyError("invalid amount '%s': expected text" % (text,))
    m = _AMOUNT_RE.fullmatch(text)
    if not m:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.groups()
    frac = frac or ""
    if "." in text and exp == 0:
        raise MoneyError("invalid amount '%s': %s has no decimals" % (text, currency))
    if len(frac) > exp:
        raise MoneyError("invalid amount '%s': %s allows at most %d decimals" % (text, currency, exp))
    minor = int(whole) * 10 ** exp + (int(frac.ljust(exp, "0")) if exp else 0)
    return -minor if sign == "-" else minor


class Money:
    __slots__ = ("minor", "currency")

    def __init__(self, minor, currency):
        if not _is_int(minor):
            raise MoneyError("amount must be an integer number of minor units, got %r" % (minor,))
        _currency(currency)
        object.__setattr__(self, "minor", minor)
        object.__setattr__(self, "currency", currency)

    def __setattr__(self, name, value):
        raise AttributeError("Money is immutable")

    def __delattr__(self, name):
        raise AttributeError("Money is immutable")

    def __reduce__(self):
        return (Money, (self.minor, self.currency))

    @classmethod
    def zero(cls, currency):
        return cls(0, currency)

    @classmethod
    def of(cls, text, currency):
        return cls(parse_amount(text, currency), currency)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("cannot read money from '%s': expected text" % (text,))
        parts = text.split(" ")
        if len(parts) != 2:
            raise MoneyError("invalid money '%s': expected AMOUNT CURRENCY" % text)
        return cls.of(parts[0], parts[1])

    @property
    def exponent(self):
        return CURRENCIES[self.currency].exponent

    def amount_str(self):
        return format_minor(self.minor, self.currency)

    def __repr__(self):
        return "Money(%d, '%s')" % (self.minor, self.currency)

    def __str__(self):
        return "%s %s" % (self.amount_str(), self.currency)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self.minor == other.minor and self.currency == other.currency

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self.minor, self.currency))

    def _same(self, other, verb):
        if self.currency != other.currency:
            raise MoneyError(
                "cannot %s %s and %s: different currencies" % (verb, self.currency, other.currency)
            )

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "add")
        return Money(self.minor + other.minor, self.currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "subtract")
        return Money(self.minor - other.minor, self.currency)

    def __neg__(self):
        return Money(-self.minor, self.currency)

    def __pos__(self):
        return self

    def __abs__(self):
        return Money(abs(self.minor), self.currency)

    def __mul__(self, other):
        if not _is_int(other):
            return NotImplemented
        return Money(self.minor * other, self.currency)

    __rmul__ = __mul__

    def _cmp(self, other):
        if not isinstance(other, Money):
            return None
        self._same(other, "compare")
        return (self.minor > other.minor) - (self.minor < other.minor)

    def __lt__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c < 0

    def __le__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c <= 0

    def __gt__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c > 0

    def __ge__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c >= 0

    def is_zero(self):
        return self.minor == 0

    def sign(self):
        return (self.minor > 0) - (self.minor < 0)

    def scale(self, num, den=1):
        if not _is_int(num) or not _is_int(den):
            raise MoneyError("scale needs integers, got %r and %r" % (num, den))
        if den == 0:
            raise MoneyError("scale denominator may not be zero")
        if den < 0:
            num, den = -num, -den
        return Money(round_div(self.minor * num, den), self.currency)

    def allocate(self, weights):
        if not isinstance(weights, (list, tuple)) or not weights:
            raise MoneyError("weights must be a non-empty list of integers")
        if not all(_is_int(w) for w in weights):
            raise MoneyError("weights must be integers: %r" % (list(weights),))
        if any(w < 0 for w in weights):
            raise MoneyError("weights may not be negative: %r" % (list(weights),))
        total = sum(weights)
        if total <= 0:
            raise MoneyError("weights must add up to more than zero")
        amount = abs(self.minor)
        shares = [amount * w // total for w in weights]
        rems = [amount * w % total for w in weights]
        left = amount - sum(shares)
        order = sorted(range(len(weights)), key=lambda i: (-rems[i], i))
        for i in order[:left]:
            shares[i] += 1
        if self.minor < 0:
            shares = [-s for s in shares]
        return [Money(s, self.currency) for s in shares]

