"""Money as integer minor units with a currency code."""
import re

from .currency import CURRENCIES, CurrencyError, currency as _currency
from .errors import ValidationError


class MoneyError(ValidationError):
    pass


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def round_div(n, d):
    if not _is_int(n) or not _is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (n, d))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %d" % d)
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return -q if n < 0 else q


def format_minor(minor, currency):
    exp = _currency(currency).exponent
    if not _is_int(minor):
        raise MoneyError("amount must be an integer number of minor units, got %r" % (minor,))
    sign = "-" if minor < 0 else ""
    whole, frac = divmod(abs(minor), 10 ** exp)
    if exp == 0:
        return "%s%d" % (sign, whole)
    return "%s%d.%s" % (sign, whole, str(frac).rjust(exp, "0"))


def parse_amount(text, currency):
    exp = _currency(currency).exponent
    if not isinstance(text, str):
        raise MoneyError("invalid amount '%s': expected text" % (text,))
    m = _AMOUNT_RE.fullmatch(text)
    if not m:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.groups()
    frac = frac or ""
    if "." in text and exp == 0:
        raise MoneyError("invalid amount '%s': %s has no decimals" % (text, currency))
    if len(frac) > exp:
        raise MoneyError("invalid amount '%s': %s allows at most %d decimals" % (text, currency, exp))
    minor = int(whole) * 10 ** exp + (int(frac.ljust(exp, "0")) if exp else 0)
    return -minor if sign == "-" else minor


class Money:
    __slots__ = ("minor", "currency")

    def __init__(self, minor, currency):
        if not _is_int(minor):
            raise MoneyError("amount must be an integer number of minor units, got %r" % (minor,))
        _currency(currency)
        object.__setattr__(self, "minor", minor)
        object.__setattr__(self, "currency", currency)

    def __setattr__(self, name, value):
        raise AttributeError("Money is immutable")

    def __delattr__(self, name):
        raise AttributeError("Money is immutable")

    def __reduce__(self):
        return (Money, (self.minor, self.currency))

    @classmethod
    def zero(cls, currency):
        return cls(0, currency)

    @classmethod
    def of(cls, text, currency):
        return cls(parse_amount(text, currency), currency)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("cannot read money from '%s': expected text" % (text,))
        parts = text.split(" ")
        if len(parts) != 2:
            raise MoneyError("invalid money '%s': expected AMOUNT CURRENCY" % text)
        return cls.of(parts[0], parts[1])

    @property
    def exponent(self):
        return CURRENCIES[self.currency].exponent

    def amount_str(self):
        return format_minor(self.minor, self.currency)

    def __repr__(self):
        return "Money(%d, '%s')" % (self.minor, self.currency)

    def __str__(self):
        return "%s %s" % (self.amount_str(), self.currency)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self.minor == other.minor and self.currency == other.currency

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self.minor, self.currency))

    def _same(self, other, verb):
        if self.currency != other.currency:
            raise MoneyError(
                "cannot %s %s and %s: different currencies" % (verb, self.currency, other.currency)
            )

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "add")
        return Money(self.minor + other.minor, self.currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "subtract")
        return Money(self.minor - other.minor, self.currency)

    def __neg__(self):
        return Money(-self.minor, self.currency)

    def __pos__(self):
        return self

    def __abs__(self):
        return Money(abs(self.minor), self.currency)

    def __mul__(self, other):
        if not _is_int(other):
            return NotImplemented
        return Money(self.minor * other, self.currency)

    __rmul__ = __mul__

    def _cmp(self, other):
        if not isinstance(other, Money):
            return None
        self._same(other, "compare")
        return (self.minor > other.minor) - (self.minor < other.minor)

    def __lt__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c < 0

    def __le__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c <= 0

    def __gt__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c > 0

    def __ge__(self, other):
        c = self._cmp(other)
        return NotImplemented if c is None else c >= 0

    def is_zero(self):
        return self.minor == 0

    def sign(self):
        return (self.minor > 0) - (self.minor < 0)

    def scale(self, num, den=1):
        if not _is_int(num) or not _is_int(den):
            raise MoneyError("scale needs integers, got %r and %r" % (num, den))
        if den == 0:
            raise MoneyError("scale denominator may not be zero")
        if den < 0:
            num, den = -num, -den
        return Money(round_div(self.minor * num, den), self.currency)

    def allocate(self, weights):
        if not isinstance(weights, (list, tuple)) or not weights:
