"""Recurring transactions: schedule words, occurrence dates and dated copies."""
import re
from dataclasses import dataclass
from datetime import date, timedelta
from typing import Optional

from .dates import DateError, format_date, is_date, last_day, parse_date
from .errors import ValidationError
from .model import Transaction

_MIN_ORD = date.min.toordinal()
_MAX_ORD = date.max.toordinal()
_T_MIN = date.min.year * 12
_T_MAX = date.max.year * 12 + 11

_WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
_WEEKDAY_NAMES = (
    "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday",
)
_MONTH_NAMES = (
    "January", "February", "March", "April", "May", "June", "July",
    "August", "September", "October", "November", "December",
)
_UNITS = {
    "day": "days", "days": "days", "week": "weeks", "weeks": "weeks",
    "month": "months", "months": "months", "year": "years", "years": "years",
}
_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_NUM_RE = re.compile(r"[0-9]+")
_YMD_RE = re.compile(r"([0-9]{2})-([0-9]{2})")

_SHAPES = (
    "daily, weekly on mon|tue|wed|thu|fri|sat|sun, monthly on 1-31, monthly on last, "
    "yearly on MM-DD, every N days|weeks|months|years from YYYY-MM-DD"
)


class RecurringError(ValidationError):
    pass


def _bad(text, why=None):
    msg = "invalid schedule '%s': expected one of: %s" % (text, _SHAPES)
    if why:
        msg += " (%s)" % why
    return RecurringError(msg)


@dataclass(frozen=True)
class Schedule:
    kind: str
    weekday: Optional[int] = None
    day: Optional[int] = None  # day of month; 0 means the last day
    month: Optional[int] = None
    step: Optional[int] = None
    unit: Optional[str] = None  # always plural
    anchor: Optional[date] = None

