        """("ap", first_ordinal, step_days) or ("mo", first_month_index, step_months, day)."""
        k = self.kind
        if k == "daily":
            return ("ap", _MIN_ORD, 1)
        if k == "weekly":
            return ("ap", _MIN_ORD + self.weekday, 7)
        if k == "monthly":
            return ("mo", _T_MIN, 1, self.day)
        if k == "yearly":
            return ("mo", _T_MIN + self.month - 1, 12, self.day)
        a = self.anchor
        if self.unit == "days":
            return ("ap", a.toordinal(), self.step)
        if self.unit == "weeks":
            return ("ap", a.toordinal(), 7 * self.step)
        step = self.step * (12 if self.unit == "years" else 1)
        return ("mo", a.year * 12 + a.month - 1, step, a.day)

    def _total(self):
        shape = self._shape()
        if shape[0] == "ap":
            _, f, s = shape
            return 0 if f > _MAX_ORD else (_MAX_ORD - f) // s + 1
        _, t0, step, _ = shape
        return 0 if t0 > _T_MAX else (_T_MAX - t0) // step + 1

    def _count_before(self, o):
        """How many of the schedule's dates have an ordinal below o."""
        o = max(_MIN_ORD, min(o, _MAX_ORD + 1))
        shape = self._shape()
        if shape[0] == "ap":
            _, f, s = shape
            return 0 if o <= f else (o - f + s - 1) // s
        _, t0, step, day = shape
        if o > _MAX_ORD:
            return self._total()
        d = date.fromordinal(o)
        tm = d.year * 12 + d.month - 1
        k = 0 if tm <= t0 else (tm - t0 + step - 1) // step
        if t0 + k * step == tm and self._month_date(tm, day) < d:
            k += 1
        return min(k, self._total())

    @staticmethod
    def _month_date(t, day):
        y, m = divmod(t, 12)
        m += 1
        ld = last_day(y, m)
        return date(y, m, ld if day == 0 else min(day, ld))

    def _nth(self, k):
        shape = self._shape()
        if shape[0] == "ap":
            _, f, s = shape
            return date.fromordinal(f + k * s)
        _, t0, step, day = shape
        return self._month_date(t0 + k * step, day)

    def between(self, start, end):
        _need_date(start, "start")
        _need_date(end, "end")
        if end < start:
            return []
        lo = self._count_before(start.toordinal())
        hi = self._count_before(end.toordinal() + 1)
        return [self._nth(i) for i in range(lo, hi)]


def _need_date(value, what):
    if not is_date(value):
        raise RecurringError("%s must be a date, got '%s'" % (what, value))


def parse_schedule(text):
    if isinstance(text, Schedule):
        raise _bad(text)
    if not isinstance(text, str):
        raise _bad(text)
    words = text.lower().split()
    n = len(words)
    if n == 1 and words[0] == "daily":
        return Schedule("daily")
    if n == 3 and words[0] == "weekly" and words[1] == "on" and words[2] in _WEEKDAYS:
        return Schedule("weekly", weekday=_WEEKDAYS.index(words[2]))
    if n == 3 and words[0] == "monthly" and words[1] == "on":
        if words[2] == "last":
            return Schedule("monthly", day=0)
        if _NUM_RE.fullmatch(words[2]) and 1 <= int(words[2]) <= 31:
            return Schedule("monthly", day=int(words[2]))
    if n == 3 and words[0] == "yearly" and words[1] == "on":
        m = _YMD_RE.fullmatch(words[2])
        if m:
            month, day = int(m.group(1)), int(m.group(2))
            if 1 <= month <= 12 and 1 <= day <= (29 if month == 2 else last_day(2001, month)):
                return Schedule("yearly", month=month, day=day)
    if n == 5 and words[0] == "every" and words[3] == "from" and words[2] in _UNITS:
        if _NUM_RE.fullmatch(words[1]) and int(words[1]) >= 1:
            try:
                anchor = parse_date(words[4])
            except DateError:
                raise _bad(text) from None
            return Schedule("every", step=int(words[1]), unit=_UNITS[words[2]], anchor=anchor)
    raise _bad(text)


def _as_schedule(value):
    if isinstance(value, Schedule):
        return value
    if isinstance(value, str):
        return parse_schedule(value)
    raise RecurringError("schedule must be a Schedule or text, got '%s'" % (value,))


class Recurring:
    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME_RE.fullmatch(name):
            raise RecurringError(
                "invalid name '%s': use letters, digits, '-' and '_', not starting with '-' or '_'" % (name,)
            )
        sched = _as_schedule(schedule)
        if not isinstance(template, Transaction):
            raise RecurringError("template must be a Transaction, got '%s'" % (template,))
        _need_date(start, "start")
        if end is not None:
            _need_date(end, "end")
            if end < start:
                raise RecurringError("end %s is before start %s" % (format_date(end), format_date(start)))
        if count is not None and (not isinstance(count, int) or isinstance(count, bool) or count < 1):
            raise RecurringError("count must be a whole number of at least 1, got '%s'" % (count,))
        self.name = name
        self.schedule = sched
        self.template = template
        self.start = start
        self.end = end
        self.count = count

    def _key(self):
        return (self.name, self.schedule, self.template, self.start, self.end, self.count)

    def __eq__(self, other):
        if not isinstance(other, Recurring):
            return NotImplemented
        return self._key() == other._key()

    __hash__ = None

    def __repr__(self):
        return "Recurring(%r, '%s', start=%s, end=%s, count=%s)" % (
            self.name, self.schedule, self.start, self.end, self.count,
        )

    def _range(self):
        """Index range [i0, i1) of the series in the schedule's own numbering."""
        sched = self.schedule
        i0 = sched._count_before(self.start.toordinal())
        i1 = sched._total()
        if self.end is not None:
            i1 = min(i1, sched._count_before(self.end.toordinal() + 1))
        if self.count is not None:
            i1 = min(i1, i0 + self.count)
        return i0, max(i0, i1)


def _need_recurring(rec):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: '%s'" % (rec,))


def _window(rec, start, end):
    _need_recurring(rec)
    _need_date(start, "start")
    _need_date(end, "end")
    if end < start:
        return range(0)
    i0, i1 = rec._range()
    lo = max(i0, rec.schedule._count_before(start.toordinal()))
    hi = min(i1, rec.schedule._count_before(end.toordinal() + 1))
    return range(lo, hi)


def occurrences(rec, start, end):
    window = _window(rec, start, end)
    return [rec.schedule._nth(i) for i in window]


def next_occurrence(rec, after):
    _need_recurring(rec)
    _need_date(after, "after")
    i0, i1 = rec._range()
    i = max(i0, rec.schedule._count_before(after.toordinal() + 1))
    return rec.schedule._nth(i) if i < i1 else None


def instantiate(rec, on):
    _need_recurring(rec)
    _need_date(on, "date")
    t = rec.template
    tags = tuple(sorted(set(t.tags) | {"recurring"}))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    if isinstance(recs, (str, bytes)) or not hasattr(recs, "__iter__"):
        raise RecurringError("recs must be a list of Recurring items")
    recs = list(recs)
    _need_date(start, "start")
    _need_date(end, "end")
    found = []
    for pos, rec in enumerate(recs):
        for on in occurrences(rec, start, end):
            found.append((on, rec.name, pos, rec))
    found.sort(key=lambda e: e[:3])
    return [instantiate(rec, on) for on, _, _, rec in found]


def _ordinal(n):
    if 10 <= n % 100 <= 20:
        return "%dth" % n
    return "%d%s" % (n, {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th"))


def describe(schedule):
    if not isinstance(schedule, Schedule):
        raise RecurringError("not a schedule: '%s'" % (schedule,))
    k = schedule.kind
    if k == "daily":
        return "every day"
    if k == "weekly":
        return "every %s" % _WEEKDAY_NAMES[schedule.weekday]
    if k == "monthly":
        if schedule.day == 0:
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(schedule.day)
    if k == "yearly":
        return "every year on %d %s" % (schedule.day, _MONTH_NAMES[schedule.month - 1])
    if schedule.step == 1:
        return "every %s from %s" % (schedule.unit[:-1], format_date(schedule.anchor))
    return "every %d %s from %s" % (schedule.step, schedule.unit, format_date(schedule.anchor))

